  const cutsByPool = poolCuts(pools, people, pot, today);
  const totals = new Map<number, bigint>(people.map((p) => [p.id, 0n]));
  for (const pool of pools) {
    const cut = cutsByPool.get(pool.id);
    if (!cut) continue;
    pool.members.forEach((m, i) => {
