package net.officefloor.hq.app.pool;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.AsOf;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.person.PersonController;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import tools.jackson.databind.json.JsonMapper;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/pools")
public class PoolController {

    /** A pool member as the screen shows it: a person, or another pool (memberPoolId); the share is a
     *  string with two decimals; from and to bound the membership, both included (null: no bound). */
    public record PoolMemberView(Long personId, Long memberPoolId, String share, LocalDate from, LocalDate to) {
        static PoolMemberView of(PoolMember member) {
            return new PoolMemberView(member.getPersonId(), member.getMemberPoolId(),
                    member.getShare().toPlainString(), member.getFrom(), member.getTo());
        }
    }

    /** A pool as the screen shows it, with its members in the order they were added. A crew shows as a
     *  pool too (crew true), its id the crew's negated so it is told apart from the sheet's pools; its
     *  members are its lead's and its members' and none is added through the pool. */
    public record PoolView(Long id, String name, List<PoolMemberView> members, boolean crew) {
        static PoolView of(PoolService.PoolWithMembers pool) {
            return new PoolView(pool.pool().getId(), pool.pool().getName(),
                    pool.members().stream().map(PoolMemberView::of).toList(), false);
        }

        static PoolView of(PoolService.CrewPool pool) {
            List<PoolMemberView> members = new ArrayList<>();
            for (int i = 0; i < pool.personIds().size(); i++) {
                members.add(new PoolMemberView(pool.personIds().get(i), null, pool.shares().get(i).toPlainString(),
                        null, null));
            }
            return new PoolView(-pool.crew().getId(), pool.crew().getName(), members, true);
        }
    }

    /** A person as a pool saw them at the end of a day: whether a retirement date was set, and the
     *  holds put on them by then. */
    public record PersonThenView(Long id, String name, boolean retired, List<PersonController.HoldView> holds) {
        static PersonThenView of(PoolHistoryService.PersonThen then) {
            return new PersonThenView(then.person().getId(), then.person().getName(), then.retired(),
                    then.holds().stream().map(PersonController.HoldView::of).toList());
        }
    }

    /** A period that has ended and, at the end of its to-date (day), the pot (two decimals; null for
     *  none), the pools and crews as pools, and the people, as they stood. */
    public record PeriodPoolsView(String period, LocalDate day, String pot, List<PoolView> pools,
            List<PersonThenView> people) {
        static PeriodPoolsView of(PoolHistoryService.PeriodPools then, JsonMapper json) {
            return then.frozen() != null ? json.readValue(then.frozen(), PeriodPoolsView.class) : of(then);
        }

        static PeriodPoolsView of(PoolHistoryService.PeriodPools then) {
            List<PoolView> pools = new ArrayList<>(then.pools().stream().map(PoolView::of).toList());
            then.crews().stream().map(PoolView::of).forEach(pools::add);
            return new PeriodPoolsView(then.period(), then.day(),
                    then.pot() != null ? then.pot().toPlainString() : null, pools,
                    then.people().stream().map(PersonThenView::of).toList());
        }
    }

    /** A pool: its name, trimmed as it is added. */
    public record PoolRequest(@NotBlank @Size(max = 255) String name) {
    }

    /** A member: a person of the sheet, or another pool of the sheet (memberPoolId), and its share
     *  percent, with an optional from-date and to-date. */
    public record PoolMemberRequest(Long personId, Long memberPoolId, @NotNull BigDecimal share, LocalDate from,
            LocalDate to) {
    }

    private final PoolService service;
    private final PoolHistoryService pastPools;
    private final JsonMapper json;

    public PoolController(PoolService service, PoolHistoryService pastPools, JsonMapper json) {
        this.service = service;
        this.pastPools = pastPools;
        this.json = json;
    }

    /** The sheet's pools, in the order they were added, then its crews as pools, in the order they were added. */
    @GetMapping
    public List<PoolView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId) {
        List<PoolView> list = new ArrayList<>(service.list(sheetId.trim()).stream().map(PoolView::of).toList());
        service.crewPools(sheetId.trim()).stream().map(PoolView::of).forEach(list::add);
        return list;
    }

    /** Each period whose to-date is on or before the sheet's today, the earliest first, with the pools
     *  as they stood at the end of it (a closed or soft-closed one's as they stood when it was closed); while the screen is set to an as-of date, that date stands in for
     *  the sheet's today. */
    @GetMapping("/by-period")
    public List<PeriodPoolsView> byPeriod(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(value = AsOf.HEADER, required = false) String asOfHeader) {
        return pastPools.byPeriod(sheetId.trim(), AsOf.parse(asOfHeader)).stream()
                .map(then -> PeriodPoolsView.of(then, json)).toList();
    }

    /** Add a pool to the sheet. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PoolView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated PoolRequest request) {
        return PoolView.of(service.add(sheetId.trim(), SignedInUser.decode(user), request.name()));
    }

    /** Add a member to one of the sheet's pools. */
    @PostMapping("/{poolId}/members")
    @ResponseStatus(HttpStatus.CREATED)
    public PoolView addMember(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long poolId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated PoolMemberRequest request) {
        return PoolView.of(service.addMember(sheetId.trim(), SignedInUser.decode(user), poolId, request.personId(),
                request.memberPoolId(), request.share(), request.from(), request.to()));
    }

    /** A blank or used name, a person already in the pool, a pool that may not be a member, a bad
     *  share, or a to-date before the from-date, is refused. */
    @ExceptionHandler({PoolRefusedException.class, DataIntegrityViolationException.class})
    @ResponseStatus(HttpStatus.CONFLICT)
    public void refused() {
    }

    @ExceptionHandler(HttpMessageNotReadableException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void unreadable() {
    }
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.crew.Crew;
import net.officefloor.hq.app.crew.CrewMember;
import net.officefloor.hq.app.crew.CrewMemberRepository;
import net.officefloor.hq.app.crew.CrewRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The pools on a sheet: each a name and its members, people or other pools of the sheet, each with a
 *  share percent. */
@Service
public class PoolService {

    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    /** The most pools a chain of pools, each a member of the one above, may hold. */
    private static final int MAX_DEPTH = 3;

    /** A pool with its members, in the order they were added. */
    public record PoolWithMembers(Pool pool, List<PoolMember> members) {
    }

    /** A crew as a pool: its name, and its lead's then its members' person ids, in the order they were
     *  added, each with its share, in the same order. */
    public record CrewPool(Crew crew, List<Long> personIds, List<BigDecimal> shares) {
    }

    private final PoolRepository pools;
    private final PoolMemberRepository members;
    private final PersonRepository people;
    private final CrewRepository crews;
    private final CrewMemberRepository crewMembers;
    private final SheetService sheets;
    private final Audit audit;

    public PoolService(PoolRepository pools, PoolMemberRepository members, PersonRepository people,
            CrewRepository crews, CrewMemberRepository crewMembers, SheetService sheets, Audit audit) {
        this.pools = pools;
        this.members = members;
        this.people = people;
        this.crews = crews;
        this.crewMembers = crewMembers;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's pools, in the order they were added, each with its members. */
    public List<PoolWithMembers> list(String sheetId) {
        return list(sheetId, null);
    }

    /** The sheet's pools as they stood at the end of a day (null: as they stand now), in the order
     *  they were added, each with its members added by then. */
    public List<PoolWithMembers> list(String sheetId, LocalDate day) {
        List<Pool> list = pools.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(p -> day == null || p.madeAsOf(day)).toList();
        Map<Long, List<PoolMember>> byPool = members
                .findByPoolIdInOrderByIdAsc(list.stream().map(Pool::getId).toList()).stream()
                .filter(m -> day == null || m.madeAsOf(day))
                .collect(Collectors.groupingBy(PoolMember::getPoolId));
        return list.stream().map(p -> new PoolWithMembers(p, byPool.getOrDefault(p.getId(), List.of()))).toList();
    }

    /** The sheet's crews as pools, in the order they were added: each the lead and the members at equal
     *  shares, 100.00 split as patrons' shares are (each rounded half to even), the remainder on the first.
     *  A lead who has left the sheet (transferred or merged away) is not among them. */
    public List<CrewPool> crewPools(String sheetId) {
        return crewPools(sheetId, null);
    }

    /** The sheet's crews as pools as they stood at the end of a day (null: as they stand now): those
     *  added by then, each with its members added by then. */
    public List<CrewPool> crewPools(String sheetId, LocalDate day) {
        List<Crew> list = crews.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(c -> day == null || c.madeAsOf(day)).toList();
        Map<Long, List<CrewMember>> byCrew = crewMembers
                .findByCrewIdInOrderByIdAsc(list.stream().map(Crew::getId).toList()).stream()
                .filter(m -> day == null || m.madeAsOf(day))
                .collect(Collectors.groupingBy(CrewMember::getCrewId));
        Set<Long> onSheet = people.findBySheetIdOrderByIdAsc(sheetId).stream().map(Person::getId)
                .collect(Collectors.toSet());
        return list.stream().map(crew -> {
            List<Long> ids = new ArrayList<>();
            ids.add(crew.getLeadId());
            byCrew.getOrDefault(crew.getId(), List.of()).forEach(m -> ids.add(m.getPersonId()));
            ids.removeIf(id -> !onSheet.contains(id));
            return new CrewPool(crew, ids, equalShares(ids.size()));
        }).toList();
    }

    /** 100.00 split equally over this many, each rounded half to even, the remainder on the first; none for none. */
    private static List<BigDecimal> equalShares(int count) {
        if (count == 0) {
            return List.of();
        }
        BigDecimal each = HUNDRED.divide(BigDecimal.valueOf(count), 2, RoundingMode.HALF_EVEN);
        List<BigDecimal> shares = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            shares.add(each);
        }
        shares.set(0, each.add(HUNDRED.subtract(each.multiply(BigDecimal.valueOf(count)))));
        return shares;
    }

    /** Add a pool, its name trimmed. Refused when the name is blank or already a pool's or a crew's on the sheet.
     *  The sheet is held locked so the same name added at the same moment is checked against itself. */
    @Transactional
    public PoolWithMembers add(String sheetId, String user, String name) {
        String key = name == null ? "" : name.trim();
        if (key.isEmpty()) {
            throw new PoolRefusedException("A pool needs a name");
        }
        sheets.lock(sheetId);
        if (pools.existsBySheetIdAndName(sheetId, key)) {
            throw new PoolRefusedException("The pool " + key + " is on the sheet already");
        }
        if (crews.existsBySheetIdAndName(sheetId, key)) {
            throw new PoolRefusedException("The crew " + key + " is a pool on the sheet already");
        }
        Pool saved = pools.saveAndFlush(new Pool(sheetId, key).madeOn(sheets.today(sheetId)));
        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + key);
        return new PoolWithMembers(saved, List.of());
    }

    /** Add a member to a pool with a share percent: more than 0.00 and at most 100.00, with up to two
     *  decimals, and an optional from-date and to-date, both included. The member is a person of the
     *  sheet, or another pool of the sheet (memberPoolId). Refused for such a share, a to-date before
     *  the from-date, a person already in the pool, a pool that is a member of a pool
     *  already, a pool that would contain itself through any chain, or a chain of pools more than
     *  three deep. */
    @Transactional
    public PoolWithMembers addMember(String sheetId, String user, Long poolId, Long personId, Long memberPoolId,
            BigDecimal share, LocalDate from, LocalDate to) {
        if (from != null && to != null && to.isBefore(from)) {
            throw new PoolRefusedException("A membership's to-date is not before its from-date");
        }
        if (share == null || share.signum() <= 0 || share.compareTo(HUNDRED) > 0
                || share.stripTrailingZeros().scale() > 2) {
            throw new PoolRefusedException("A share is more than 0.00 and at most 100.00, with two decimals");
        }
        if ((personId == null) == (memberPoolId == null)) {
            throw new PoolRefusedException("A member is a person or a pool");
        }
        BigDecimal scaled = share.setScale(2, RoundingMode.UNNECESSARY);
        sheets.lock(sheetId);
        Pool pool = pools.findByIdAndSheetId(poolId, sheetId)
                .orElseThrow(() -> new PoolRefusedException("No such pool on the sheet"));
        String name;
        if (personId != null) {
            Person person = people.findByIdAndSheetId(personId, sheetId)
                    .orElseThrow(() -> new PoolRefusedException("No such person on the sheet"));
            if (members.existsByPoolIdAndPersonId(poolId, personId)) {
                throw new PoolRefusedException(person.getName() + " is in the pool " + pool.getName() + " already");
            }
            members.saveAndFlush(
                    new PoolMember(poolId, personId, scaled).dated(from, to).madeOn(sheets.today(sheetId)));
            name = person.getName();
        } else {
            Pool member = pools.findByIdAndSheetId(memberPoolId, sheetId)
                    .orElseThrow(() -> new PoolRefusedException("No such pool on the sheet"));
            checkNesting(sheetId, pool, member);
            members.saveAndFlush(
                    PoolMember.ofPool(poolId, memberPoolId, scaled).dated(from, to).madeOn(sheets.today(sheetId)));
            name = member.getName();
        }
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
                + " name=" + name + " share=" + scaled.toPlainString() + (from != null ? " from=" + from : "")
                + (to != null ? " to=" + to : ""));
        return new PoolWithMembers(pool, members.findByPoolIdInOrderByIdAsc(List.of(poolId)));
    }

    /** Refuse making the pool member a member of the pool when it is a member of a pool already, when
     *  the pool is the member or lies inside it, or when the chain of pools would be more than three
     *  deep. */
    private void checkNesting(String sheetId, Pool pool, Pool member) {
        if (members.findByMemberPoolId(member.getId()).isPresent()) {
            throw new PoolRefusedException("The pool " + member.getName() + " is a member of a pool already");
        }
        Map<Long, Long> parentOf = new HashMap<>();
        Map<Long, List<Long>> childrenOf = new HashMap<>();
        List<Long> ids = pools.findBySheetIdOrderByIdAsc(sheetId).stream().map(Pool::getId).toList();
        for (PoolMember m : members.findByPoolIdInOrderByIdAsc(ids)) {
            if (m.getMemberPoolId() != null) {
                parentOf.put(m.getMemberPoolId(), m.getPoolId());
                childrenOf.computeIfAbsent(m.getPoolId(), k -> new ArrayList<>()).add(m.getMemberPoolId());
            }
        }
        // The pools from the pool up to the top, the pool counted.
        int above = 0;
        for (Long at = pool.getId(); at != null; at = parentOf.get(at)) {
            if (at.equals(member.getId())) {
                throw new PoolRefusedException("The pool " + pool.getName() + " would contain itself");
            }
            above++;
        }
        if (above + height(member.getId(), childrenOf) > MAX_DEPTH) {
            throw new PoolRefusedException("A chain of pools is at most " + MAX_DEPTH + " deep");
        }
    }

    /** The pools in the longest chain down from this pool, the pool counted. */
    private int height(Long poolId, Map<Long, List<Long>> childrenOf) {
        int below = 0;
        for (Long child : childrenOf.getOrDefault(poolId, List.of())) {
            below = Math.max(below, height(child, childrenOf));
        }
        return below + 1;
    }
}
